import sys, unicodedata, json, binascii
assert sys.version_info[:3] == (3,14,7)
assert unicodedata.unidata_version == '16.0.0'
assert sys.platform == 'darwin' and sys.byteorder == 'little'
data=json.load(sys.stdin)
for raw, newline, expected in data['encode']:
 assert binascii.b2a_base64(bytes.fromhex(raw),newline=newline).hex()==expected
for raw, strict, expected, message in data['decode']:
 try:
  actual=binascii.a2b_base64(bytes.fromhex(raw),strict_mode=strict).hex()
 except binascii.Error as e:
  assert str(e)==message
 else:
  assert message is None and actual==expected
print(json.dumps({'version':sys.version,'unicode':unicodedata.unidata_version,'encode':len(data['encode']),'decode':len(data['decode'])}))
